    venue: CatalogVenue,
    opts: { limit?: number; query?: string; refetchInterval?: number } = {},
): QueryState<PmxtEvent[]> {
    const { client } = usePmxt();
    return usePmxtQuery(
        ['events', venue, opts.limit, opts.query],
        () => client.fetchEvents(venue, opts),
        { refetchInterval: opts.refetchInterval ?? 60_000 },
    );
}

